        id: nativeRecorder
        interval: 50
        repeat: true
        onTriggered: {
            const elapsed = Date.now() - reviewWindow.nativeRecordStarted
            if (elapsed > reviewWindow.nativeRecordDuration) {
                stop()
                console.info("[UIReview] native recording", JSON.stringify({
                    prefix: reviewWindow.nativeRecordPrefix,
                    requestedInterval: interval,
                    duration: elapsed,
                    frames: reviewWindow.nativeRecordedFrames
                }))
                return
            }
            const index = reviewWindow.nativeRecordedFrames.length
            const path = reviewWindow.nativeRecordPrefix + "-" + String(index).padStart(4, "0") + ".png"
            const saved = pointerDriver.capture(reviewWindow, path)
            reviewWindow.nativeRecordedFrames.push({path: path, elapsedMs: elapsed,
